#define FONT_CJK_COUNT (sizeof(font_cjk) / sizeof(font_cjk[0]))

static const font_cjk_glyph_t *font_cjk_find(uint32_t codepoint)
{
    for (size_t i = 0; i < FONT_CJK_COUNT; i++) {
        if (font_cjk[i].codepoint == codepoint) return &font_cjk[i];
    }
    return NULL;
}
